package felt

import (
	"bytes"
	"fmt"
	"reflect"
	"sort"
	"strings"

	"gopkg.in/yaml.v3"
)

type documentEdit struct {
	start, end int
	text       string
}

// mutationBytes applies only fields whose values the callback changed. Authored
// scalar style, comments, key order and unknown fields outside those edits stay
// intact. The comparison snapshots are generated by the same Felt marshaler.
func mutationBytes(raw, before, after []byte, oldBody, newBody string) ([]byte, error) {
	start, close, bodyStart, err := frontmatterBounds(raw)
	if err != nil {
		return nil, err
	}
	parse := func(data []byte) (*yaml.Node, error) {
		begin, end, _, err := frontmatterBounds(data)
		if err != nil {
			return nil, err
		}
		var doc yaml.Node
		if err := yaml.Unmarshal(data[begin:end], &doc); err != nil {
			return nil, err
		}
		if len(doc.Content) == 0 {
			return &yaml.Node{Kind: yaml.MappingNode}, nil
		}
		return doc.Content[0], nil
	}
	original, err := parse(raw)
	if err != nil {
		return nil, err
	}
	previous, err := parse(before)
	if err != nil {
		return nil, err
	}
	updated, err := parse(after)
	if err != nil {
		return nil, err
	}
	lines := strings.Split(string(raw[start:close]), "\n")
	var edits []documentEdit
	var visit func(*yaml.Node, *yaml.Node, *yaml.Node, int, int) error
	visit = func(current, old, next *yaml.Node, end, indent int) error {
		keys := map[string]bool{}
		for _, mapping := range []*yaml.Node{old, next} {
			if mapping != nil {
				for i := 0; i+1 < len(mapping.Content); i += 2 {
					keys[mapping.Content[i].Value] = true
				}
			}
		}
		ordered := make([]string, 0, len(keys))
		for key := range keys {
			ordered = append(ordered, key)
		}
		sort.Strings(ordered)
		for _, key := range ordered {
			prior := MappingValueNode(old, key)
			value := MappingValueNode(next, key)
			if equalNodeValue(prior, value) {
				continue
			}
			rawValue := MappingValueNode(current, key)
			begin, finish := end, end
			if rawValue != nil {
				for i := 0; i+1 < len(current.Content); i += 2 {
					if current.Content[i].Value == key {
						begin = current.Content[i].Line - 1
						if i+2 < len(current.Content) {
							finish = current.Content[i+2].Line - 1
						}
						break
					}
				}
			}
			if rawValue != nil && prior != nil && value != nil && rawValue.Kind == yaml.MappingNode && rawValue.Style&yaml.FlowStyle == 0 && prior.Kind == yaml.MappingNode && value.Kind == yaml.MappingNode {
				childIndent := indent + 2
				if len(rawValue.Content) > 0 {
					childIndent = rawValue.Content[0].Column - 1
				}
				if err := visit(rawValue, prior, value, finish, childIndent); err != nil {
					return err
				}
				continue
			}
			text := ""
			if value != nil {
				entry := &yaml.Node{Kind: yaml.MappingNode, Content: []*yaml.Node{{Kind: yaml.ScalarNode, Tag: "!!str", Value: key}, value}}
				var buf bytes.Buffer
				enc := yaml.NewEncoder(&buf)
				enc.SetIndent(2)
				if err := enc.Encode(entry); err != nil {
					return fmt.Errorf("encoding changed field %s: %w", key, err)
				}
				rendered := strings.TrimSuffix(buf.String(), "\n")
				prefix := strings.Repeat(" ", indent)
				text = prefix + strings.ReplaceAll(rendered, "\n", "\n"+prefix) + "\n"
			}
			edits = append(edits, documentEdit{begin, finish, text})
		}
		return nil
	}
	end := len(lines) - 1
	if err := visit(original, previous, updated, end, 0); err != nil {
		return nil, err
	}
	// Stable ordering keeps additions at the same mapping boundary deterministic.
	sort.SliceStable(edits, func(i, j int) bool { return edits[i].start > edits[j].start })
	for _, edit := range edits {
		replacement := strings.TrimSuffix(edit.text, "\n")
		var insert []string
		if edit.text != "" {
			insert = strings.Split(replacement, "\n")
		}
		lines = append(append(append([]string{}, lines[:edit.start]...), insert...), lines[edit.end:]...)
	}
	body := string(raw[bodyStart:])
	if oldBody != newBody {
		if oldBody != "" {
			at := strings.Index(body, oldBody)
			body = body[:at] + newBody + body[at+len(oldBody):]
		} else {
			body = "\n" + newBody + "\n"
		}
	}
	result := append([]byte(nil), raw[:start]...)
	result = append(result, []byte(strings.Join(lines, "\n"))...)
	result = append(result, raw[close:bodyStart]...)
	return append(result, []byte(body)...), nil
}

func equalNodeValue(a, b *yaml.Node) bool {
	if a == nil || b == nil {
		return a == b
	}
	var x, y any
	if a.Decode(&x) != nil || b.Decode(&y) != nil {
		return false
	}
	return reflect.DeepEqual(x, y)
}
